/**
 * Jinx Alchemist + Spy: rules tests.
 *
 * Wiki: https://wiki.bloodontheclocktower.com/Alchemist
 * Wiki: https://wiki.bloodontheclocktower.com/Spy
 * (the wiki has no jinx page; each character's page lists the jinx under "Related Jinxes")
 *
 * Generated by `npm run scaffold:rules-tests`, then filled in (L119). Each test quotes the
 * jinx as the wiki words it, word for word, in a `// Wiki: "..."` comment (Trevor, 2026-11-01).
 */
import { describe, expect, it } from 'vitest';
import { findJinx, jinxesAmong } from '#lib/core/data/index.ts';
import { committedGameData } from '#lib/core/testing/committed-data.ts';
import { abilityState } from '#lib/core/rules/ability.ts';
import { hasAbilityOf } from '#lib/core/rules/gained-abilities.ts';
import { jinxRulesBetween } from '#lib/core/rules/jinxes.ts';
import { jinxGuessers } from '#lib/core/rules/jinx-effects.ts';
import { nightStepAlerts } from '#lib/core/rules/night-alerts.ts';
import { alchemistAs, bagNotes } from './alchemist.test-support.ts';

describe('Alchemist + Spy jinx', () => {
	const data = committedGameData();
	const jinx = findJinx(data.jinxes, 'alchemist', 'spy');

	it('is in jinxes.json between two official characters', () => {
		expect(data.byId.get('alchemist')?.name).toBe('Alchemist');
		expect(data.byId.get('spy')?.name).toBe('Spy');
		expect(jinx).toBeDefined();
		expect(jinx?.reason).not.toBe('');
	});

	it('applies only when both characters are on the script', () => {
		expect(jinxesAmong(data.jinxes, ['alchemist', 'spy'])).toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['alchemist'])).not.toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['spy'])).not.toContain(jinx);
	});

	it("is data in the Alchemist's rules", () => {
		// Wiki: "An Alchemist-Spy has no Spy ability & a Spy is in play. After each execution, a living Alchemist-Spy may publicly guess a living player as the Spy. If correct, the Demon must choose the Spy tonight."
		expect(jinxRulesBetween('alchemist', 'spy')).toEqual({
			withPartnerAbility: 'partner-in-play',
			guessesPartner: true
		});
	});

	// Seat 0 the Alchemist-Spy, seat 2 the real Spy.
	const base = alchemistAs('spy', ['chef', 'spy', 'imp', 'empath']);
	const guesses = (s: typeof base) => jinxGuessers(s.game, s.characters);
	const alerts = (s: typeof base) =>
		nightStepAlerts(s.game, 'imp', s.characters).filter((a) => a.kind === 'guessed');

	describe('an Alchemist-Spy has no Spy ability, and a Spy is in play', () => {
		it('notes the real Spy at setup when the Alchemist is chosen', () => {
			// Wiki: "a Spy is in play"
			const note =
				'Alchemist with the Spy ability: the Spy is in play too, and the Alchemist has no ability.';
			expect(bagNotes('spy')).toContain(note);
			expect(bagNotes('spy', false)).not.toContain(note);
		});

		it('leaves the Alchemist-Spy with no ability, and the real Spy with theirs', () => {
			// Wiki: "An Alchemist-Spy has no Spy ability"
			const state = abilityState(base.game, base.seat(0), base.characters);
			expect(state.works).toBe(false);
			expect(state.impairments).toMatchObject([
				{ reason: 'no-ability', source: { characterId: 'spy' } }
			]);
			expect(hasAbilityOf(base.game, base.seat(0), 'spy', base.characters)).toBe(false);
			expect(hasAbilityOf(base.game, base.seat(2), 'spy', base.characters)).toBe(true);
		});
	});

	describe('after each execution, a living Alchemist-Spy may guess the Spy', () => {
		it('lets them guess once someone has been executed today', () => {
			// Wiki: "After each execution, a living Alchemist-Spy may publicly guess a living player as the Spy."
			expect(guesses(base)).toEqual([]);
			const s = base.execute('chef');
			expect(guesses(s)).toEqual([
				{ seatId: s.seat(0), owner: 'alchemist', partner: 'spy', partnerSeats: [s.seat(2)] }
			]);
		});

		it('says at the Demon step that a right guess makes the Demon choose the Spy', () => {
			// Wiki: "If correct, the Demon must choose the Spy tonight."
			const s = base.execute('chef');
			expect(alerts(s)).toMatchObject([
				{ kind: 'guessed', seatId: s.seat(0), partner: 'spy', works: true }
			]);
			expect(alerts(base)).toEqual([]);
		});

		it('gives a dead Alchemist-Spy no guess, nor one with no living Spy', () => {
			// Wiki: "a living Alchemist-Spy may publicly guess a living player as the Spy"
			expect(guesses(base.dies(0).execute('chef'))).toEqual([]);
			expect(guesses(base.dies(2).execute('chef'))).toEqual([]);
		});
	});
});
